class GestureDetector:
    """Real-time hand gesture detection using MediaPipe"""
    
    def __init__(self, model_path: Optional[str] = None):
        self.mp_hands = mp.solutions.hands
        self.hands = self.mp_hands.Hands(
            static_image_mode=False,
            max_num_hands=2,
            min_detection_confidence=0.7,
            min_tracking_confidence=0.5
        )
        
        # Gesture classifier (RandomForest)
        self.classifier = RandomForestClassifier(n_estimators=100, max_depth=10)
        if model_path:
            with open(model_path, 'rb') as f:
                self.classifier = pickle.load(f)
        else:
            # Initialize with dummy classifier for demo
            self.classifier.fit(np.random.randn(100, 63), np.random.randint(0, 2, 100))
        
        self.mp_draw = mp.solutions.drawing_utils
        
    def extract_landmarks(self, image: np.ndarray) -> Optional[np.ndarray]:
        """Extract 21 hand landmarks (63-dim vector)"""
        rgb = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)
        results = self.hands.process(rgb)
        
        if not results.multi_hand_landmarks:
            return None
        
        # Use first detected hand
        landmarks = results.multi_hand_landmarks[0]
        coords = []
        for lm in landmarks.landmark:
            coords.extend([lm.x, lm.y, lm.z])
        
        return np.array(coords)
    
    def classify_gesture(self, landmarks: np.ndarray) -> GestureEvent:
        """Classify gesture from landmarks"""
        if landmarks is None:
            return GestureEvent('NONE', 0.0)
        
        # Predict gesture class and confidence
        probs = self.classifier.predict_proba(landmarks.reshape(1, -1))[0]
        pred = self.classifier.predict(landmarks.reshape(1, -1))[0]
        confidence = np.max(probs)
        
        gesture_type = 'PALM_STOP' if pred == 1 and confidence > 0.85 else 'NONE'
        
        return GestureEvent(gesture_type, confidence, landmarks)

