class SafetyFusionEngine:
    """Fuses TTF predictions with gesture detection for safety commands"""
    
    def __init__(self, ttf_model: TTFModel, gesture_detector: GestureDetector):
        self.ttf_model = ttf_model
        self.gesture_detector = gesture_detector
        self.prev_rpm = 0.0
        self.prev_timestamp = 0.0
        
        # GPIO simulation (replace with actual RPi.GPIO or Jetson GPIO)
        self.gpio_pin = 23
        self._setup_gpio()
        
        # Safety state
        self.current_level = SafetyLevel.NORMAL
        self.last_safety_command: Optional[SafetyCommand] = None
        
    def _setup_gpio(self):
        """Initialize GPIO for emergency brake signal"""
        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.OUT)
            GPIO.output(self.gpio_pin, GPIO.LOW)
            logger.info(f"GPIO pin {self.gpio_pin} initialized for emergency brake")
        except ImportError:
            logger.warning("RPi.GPIO not available - running in simulation mode")
    
    def _trigger_emergency_brake(self):
        """Send emergency brake signal to motor controller"""
        try:
            import RPi.GPIO as GPIO
            GPIO.output(self.gpio_pin, GPIO.HIGH)
            logger.critical("EMERGENCY BRAKE SIGNAL SENT - GPIO HIGH")
        except ImportError:
            logger.critical("SIMULATION: Emergency brake signal would be sent")
    
    def _release_brake(self):
        """Release emergency brake"""
        try:
            import RPi.GPIO as GPIO
            GPIO.output(self.gpio_pin, GPIO.LOW)
            logger.info("Emergency brake released")
        except ImportError:
            logger.info("SIMULATION: Emergency brake released")
    
    def determine_safety_level(self, ttf: float, gesture: GestureEvent) -> SafetyLevel:
        """Determine safety level based on TTF and gesture"""
        # Gesture override takes highest priority
        if gesture.gesture_type == 'PALM_STOP' and gesture.confidence > 0.85:
            return SafetyLevel.EMERGENCY_STOP
        
        # TTF-based levels
        if ttf < 3.0:
            return SafetyLevel.RED
        elif ttf < 10.0:
            return SafetyLevel.ORANGE
        elif ttf < 30.0:
            return SafetyLevel.YELLOW
        else:
            return SafetyLevel.NORMAL
    
    async def process_frame(self, frame: SensorFrame, image: Optional[np.ndarray] = None) -> SafetyCommand:
        """Process a single sensor frame and return safety command"""
        dt = frame.timestamp - self.prev_timestamp if self.prev_timestamp > 0 else 0.001
        
        # Parallel execution of TTF and gesture detection
        ttf_task = asyncio.create_task(
            asyncio.to_thread(self.ttf_model.predict, frame, self.prev_rpm, dt)
        )
        
        gesture_task = asyncio.create_task(
            asyncio.to_thread(self._detect_gesture, image)
        ) if image is not None else None
        
        # Await TTF
        ttf = await ttf_task
        
        # Await gesture if available
        gesture = GestureEvent('NONE', 0.0)
        if gesture_task:
            gesture = await gesture_task
        
        # Determine safety level
        level = self.determine_safety_level(ttf, gesture)
        
        # Execute safety actions
        brake_signal = False
        if level == SafetyLevel.EMERGENCY_STOP:
            self._trigger_emergency_brake()
            brake_signal = True
        elif level == SafetyLevel.RED:
            self._trigger_emergency_brake()
            brake_signal = True
        elif level == SafetyLevel.ORANGE:
            # Reduce speed by 75% (simulated)
            logger.warning(f"ORANGE alert: Reducing speed by 75% (TTF={ttf:.2f}s)")
        elif level == SafetyLevel.YELLOW:
            # Reduce speed by 50% (simulated)
            logger.warning(f"YELLOW alert: Reducing speed by 50% (TTF={ttf:.2f}s)")
        else:
            # Release brake if previously engaged
            if self.current_level in [SafetyLevel.RED, SafetyLevel.EMERGENCY_STOP]:
                self._release_brake()
        
        # Update state
        self.current_level = level
        self.prev_rpm = frame.rpm
        self.prev_timestamp = frame.timestamp
        
        command = SafetyCommand(
            level=level,
            ttf_seconds=ttf,
            gesture_override=(gesture.gesture_type == 'PALM_STOP'),
            brake_signal=brake_signal,
            timestamp=frame.timestamp
        )
        self.last_safety_command = command
        
        return command
    
    async def _detect_gesture(self, image: np.ndarray) -> GestureEvent:
        """Async wrapper for gesture detection"""
        if image is None:
            return GestureEvent('NONE', 0.0)
        
        landmarks = self.gesture_detector.extract_landmarks(image)
        return self.gesture_detector.classify_gesture(landmarks)

