async def main():
    """Main safety loop - runs at 30Hz"""
    # Initialize models
    ttf_model = TTFModel()
    gesture_detector = GestureDetector()
    safety_engine = SafetyFusionEngine(ttf_model, gesture_detector)
    
    # Camera capture
    cap = cv2.VideoCapture(0)
    cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
    cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
    cap.set(cv2.CAP_PROP_FPS, 30)
    
    # Sensor simulation (replace with actual sensor drivers)
    sensor_buffer = deque(maxlen=1024)
    
    logger.info("Safety Fusion Engine started - monitoring for TTF and PALM_STOP")
    
    try:
        while True:
            loop_start = asyncio.get_event_loop().time()
            
            # Capture frame
            ret, image = cap.read()
            if not ret:
                logger.error("Failed to capture camera frame")
                await asyncio.sleep(0.033)
                continue
            
            # Simulate sensor frame (replace with actual sensor reading)
            frame = SensorFrame(
                timestamp=loop_start,
                vibration_x=np.sin(np.linspace(0, 2*np.pi, 1024)) * 0.5 + np.random.randn(1024) * 0.1,
                vibration_y=np.cos(np.linspace(0, 2*np.pi, 1024)) * 0.3 + np.random.randn(1024) * 0.1,
                vibration_z=np.sin(np.linspace(0, 4*np.pi, 1024)) * 0.2 + np.random.randn(1024) * 0.1,
                thermal_array=np.random.randn(32, 32) * 5 + 50,  # 50°C baseline
                rpm=1500 + np.random.randn() * 50,
                current_rms=12.5 + np.random.randn() * 0.5
            )
            
            # Process safety
            command = await safety_engine.process_frame(frame, image)
            
            # Log safety state
            if command.level != SafetyLevel.NORMAL:
                logger.warning(
                    f"Safety Level: {command.level.name} | "
                    f"TTF: {command.ttf_seconds:.2f}s | "
                    f"Gesture Override: {command.gesture_override} | "
                    f"Brake: {command.brake_signal}"
                )
            
            # Maintain 30Hz loop
            elapsed = asyncio.get_event_loop().time() - loop_start
            sleep_time = max(0, 0.033 - elapsed)
            await asyncio.sleep(sleep_time)
            
    except KeyboardInterrupt:
        logger.info("Shutting down safety engine")
    finally:
        cap.release()
        cv2.destroyAllWindows()
        safety_engine._release_brake()

if __name__ == "__main__":
    asyncio.run(main())